CREATE TABLE IF NOT EXISTS rice_accounts(user_id INTEGER PRIMARY KEY REFERENCES users(id), active INTEGER NOT NULL DEFAULT 1, can_adjust INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS rice_products(id INTEGER PRIMARY KEY, sku TEXT UNIQUE NOT NULL, name TEXT NOT NULL, model_class TEXT UNIQUE NOT NULL, description TEXT NOT NULL DEFAULT '25 kg rice sack', quantity INTEGER NOT NULL DEFAULT 0 CHECK(quantity>=0), version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS rice_actions(id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), kind TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'open', revision INTEGER NOT NULL DEFAULT 0, snapshot TEXT NOT NULL, comparison TEXT NOT NULL DEFAULT '[]', details TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rice_images(id TEXT PRIMARY KEY, action_id TEXT NOT NULL REFERENCES rice_actions(id), deleted INTEGER NOT NULL DEFAULT 0, reviewed INTEGER NOT NULL DEFAULT 0, image TEXT NOT NULL, image_hash TEXT NOT NULL, raw TEXT NOT NULL, checked TEXT NOT NULL DEFAULT '[]', processing_ms TEXT NOT NULL, model_version TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rice_requests(id TEXT PRIMARY KEY, payload_hash TEXT NOT NULL, result TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rice_history(id TEXT PRIMARY KEY, action_id TEXT NOT NULL REFERENCES rice_actions(id), product_id INTEGER NOT NULL REFERENCES rice_products(id), kind TEXT NOT NULL, previous_quantity INTEGER NOT NULL, quantity INTEGER NOT NULL, difference INTEGER NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id), reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rice_cases(id TEXT PRIMARY KEY, action_id TEXT NOT NULL REFERENCES rice_actions(id), product_id INTEGER NOT NULL REFERENCES rice_products(id), kind TEXT NOT NULL, quantity INTEGER NOT NULL, remaining INTEGER NOT NULL, already_stocked INTEGER NOT NULL, condition TEXT NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending inspection', user_id INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rice_decisions(id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES rice_cases(id), decision TEXT NOT NULL, quantity INTEGER NOT NULL, difference INTEGER NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id), reason TEXT NOT NULL, created_at TEXT NOT NULL);
